args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?earliest ?label ?birthDate WHERE {
  VALUES ?person { dbr:David_Fennario dbr:Peter_Emanuel_Falck }
  OPTIONAL { ?person rdfs:label ?label FILTER (lang(?label) = 'en') }
  OPTIONAL { ?person dbo:birthDate ?bd1 }
  OPTIONAL { ?person dbp:birthDate ?bd2 }
  OPTIONAL { ?person dbp:born ?bd3 }
  BIND(coalesce(?bd1, ?bd2, ?bd3) AS ?birthDate)
  BIND(?person AS ?earliest)
}
ORDER BY ASC(?birthDate)
LIMIT 1

PREFIX dbr: <http://dbpedia.org/resource/>
SELECT ?p ?o WHERE {
  dbr:David_Fennario ?p ?o .
  FILTER (regex(str(?o), "1947"))
}

PREFIX dbr: <http://dbpedia.org/resource/>
SELECT ?p ?o WHERE {
  dbr:Peter_Emanuel_Falck ?p ?o .
  FILTER (regex(str(?o), "1952"))
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dc: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?earliest ?label ?year WHERE {
  VALUES ?p { dbr:David_Fennario dbr:Peter_Emanuel_Falck }
  OPTIONAL { ?p rdfs:label ?label FILTER(lang(?label) = 'en') }
  OPTIONAL { ?p dbo:birthYear ?by }
  OPTIONAL { ?p dbo:birthDate ?bd }
  OPTIONAL { ?p dbp:birthDate ?bd2 }
  OPTIONAL { ?p dc:subject ?cat FILTER(regex(str(?cat), "_births")) }

  BIND(
    COALESCE(
      (IF(bound(?by), STR(?by), NULL)),
      (IF(bound(?bd), SUBSTR(str(?bd), 1, 4), NULL)),
      (IF(bound(?bd2), SUBSTR(str(?bd2), 1, 4), NULL)),
      (IF(bound(?cat), REPLACE(str(?cat), '^.*?(\\d{4}).*$', '$1'), NULL))
    ) AS ?yearStr
  )
  BIND(xsd:integer(?yearStr) AS ?year)
  BIND(?p AS ?earliest)
}
ORDER BY ASC(?year)
LIMIT 1

